import{_ as e,o,c as a,a2 as d}from"./chunks/framework.DhQimoSI.js";const f=JSON.parse('{"title":"The SDK","description":"","frontmatter":{},"headers":[],"relativePath":"sdk/index.md","filePath":"sdk/index.md"}'),r={name:"sdk/index.md"};function s(i,t,n,c,h,l){return o(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="the-sdk" tabindex="-1">The SDK <a class="header-anchor" href="#the-sdk" aria-label="Permalink to &quot;The SDK&quot;">​</a></h1><p>The reference implementation is the code that reads and writes Mosaic in this repository. It is one correct reading of the <a href="/mosaic/dist/docs/standard/file/">standard</a>, not the standard itself.</p><table tabindex="0"><thead><tr><th>Package</th><th>What it is</th></tr></thead><tbody><tr><td><a href="https://github.com/tomvandig/mosaic/tree/main/sdk/ts/" target="_blank" rel="noreferrer"><code>sdk/ts</code></a> (<code>mosaic-ts</code>)</td><td>The core library: archives, packing, federation, selection, composition, glTF and SVG conversion, DuckDB, and the HTTP client and server</td></tr><tr><td><a href="https://github.com/tomvandig/mosaic/tree/main/sdk/ifc4/" target="_blank" rel="noreferrer"><code>sdk/ifc4</code></a> (<code>mosaic-ifc4</code>)</td><td>IFC4 / IFC2X3 conversion, on top of web-ifc</td></tr><tr><td><a href="https://github.com/tomvandig/mosaic/tree/main/sdk/cli/" target="_blank" rel="noreferrer"><code>sdk/cli</code></a> (<code>mosaic</code>)</td><td>The command line, bundled into a single executable. See <a href="/mosaic/dist/docs/tools/">The CLI</a></td></tr><tr><td><code>sdk/ts/src/viewer</code></td><td>The browser viewer, built for both <code>mosaic serve</code> and the <a href="/mosaic/dist/docs/examples/">static examples</a></td></tr></tbody></table><h2 id="how-it-follows-the-standard" tabindex="-1">How it follows the standard <a class="header-anchor" href="#how-it-follows-the-standard" aria-label="Permalink to &quot;How it follows the standard&quot;">​</a></h2><p>The SDK doesn&#39;t define its own file types. <code>MosaicIndexFile.ts</code> is <strong>generated</strong> from <code>standard/mosaic-index-file.schema.json</code> with quicktype, and the API client, routes and types in <code>sdk/ts/src/api/</code> are generated from <code>standard/mosaic-api.openapi3.json</code>. When the standard changes, regenerating them is what carries the change through, and a mismatch shows up as a type error.</p><p>The server routes off the generated table of operations, so a test can assert that every operation in the spec has a handler.</p><h2 id="what-the-implementation-adds" tabindex="-1">What the implementation adds <a class="header-anchor" href="#what-the-implementation-adds" aria-label="Permalink to &quot;What the implementation adds&quot;">​</a></h2><p>Everything below is built <em>on</em> the standard. A file produced this way is a valid Mosaic file, but another implementation is not required to offer these features:</p><table tabindex="0"><thead><tr><th>Feature</th><th>Notes</th><th>Docs</th></tr></thead><tbody><tr><td><strong>The <code>.tsr</code> archive</strong></td><td>A zip with <code>index.json</code> and <code>&lt;type&gt;.ndjson</code> per table, deflated at level 6</td><td><a href="/mosaic/dist/docs/standard/file/format">The format</a></td></tr><tr><td><strong>Source documents</strong></td><td><code>.mosaic.json</code>, the index plus component rows in one readable file, packed into an archive</td><td><a href="/mosaic/dist/docs/tools/pack">Packing</a></td></tr><tr><td><strong>Component namespaces</strong></td><td><code>core::</code>, <code>khronos::gltf::</code>, <code>w3c::</code>, <code>ifc4::</code> and their schemas</td><td><a href="/mosaic/dist/docs/standard/core-components">Core components</a></td></tr><tr><td><strong>Composition</strong></td><td>Imports followed, sections collapsed, <code>core::inherit</code> expanded, <code>core::child</code> turned into a glTF hierarchy</td><td><a href="/mosaic/dist/docs/tools/compose">Composing</a></td></tr><tr><td><strong>Converters</strong></td><td>glTF / GLB, IFC and SVG into Mosaic, with stable ids where asked</td><td><a href="/mosaic/dist/docs/tools/gltf">glTF</a>, <a href="/mosaic/dist/docs/tools/ifc">IFC</a>, <a href="/mosaic/dist/docs/tools/svg">SVG</a></td></tr><tr><td><strong>Federation &amp; diff</strong></td><td>Merging files with shifted references; computing the section between two files</td><td><a href="https://github.com/tomvandig/mosaic/blob/main/sdk/ts/src/MosaicFileOperations.ts" target="_blank" rel="noreferrer">source</a></td></tr><tr><td><strong>Selection</strong></td><td>A subset of nodes as a file of its own, made whole</td><td><a href="https://github.com/tomvandig/mosaic/blob/main/sdk/ts/src/Selection.ts" target="_blank" rel="noreferrer">source</a></td></tr><tr><td><strong>DuckDB storage</strong></td><td>One table per component type, built from each archive&#39;s schemas</td><td><a href="/mosaic/dist/docs/sdk/duckdb">DuckDB</a></td></tr><tr><td><strong>The server</strong></td><td>The OpenAPI operations over DuckDB, plus the page&#39;s own <code>/app/*</code> endpoints, which are <em>not</em> part of the spec</td><td><a href="/mosaic/dist/docs/sdk/http-api">HTTP API</a></td></tr><tr><td><strong>The viewer</strong></td><td>Tree, components and a 3D view, in the browser</td><td><a href="/mosaic/dist/docs/examples/">Examples</a></td></tr></tbody></table><h2 id="where-it-falls-short-of-the-standard" tabindex="-1">Where it falls short of the standard <a class="header-anchor" href="#where-it-falls-short-of-the-standard" aria-label="Permalink to &quot;Where it falls short of the standard&quot;">​</a></h2><p>The standard declares a few things the implementation does not do yet. If you depend on any of these, check the code first:</p><table tabindex="0"><thead><tr><th>In the standard</th><th>In the reference implementation</th></tr></thead><tbody><tr><td><code>ComponentTableReference.type</code> may be <code>PARQUET</code></td><td>Archives are read and written as NDJSON only. Parquet is recorded, not read</td></tr><tr><td><code>ImportNode.integrity</code> pins an import by hash</td><td>Stored and carried through, but not verified when an import is resolved</td></tr><tr><td>The query operation of the API</td><td>Answers <code>501 Not Implemented</code></td></tr></tbody></table><h2 id="in-this-section" tabindex="-1">In this section <a class="header-anchor" href="#in-this-section" aria-label="Permalink to &quot;In this section&quot;">​</a></h2><ul><li><a href="/mosaic/dist/docs/sdk/duckdb">Querying with DuckDB</a>: loading archives into a database and querying them with SQL.</li><li><a href="/mosaic/dist/docs/sdk/http-api">The HTTP API</a>: the reference server for the <a href="/mosaic/dist/docs/standard/api">API standard</a>.</li></ul>',14)])])}const p=e(r,[["render",s]]);export{f as __pageData,p as default};
